import { revalidatePath } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreferenceEnabled,
} from './data'

/**
 * Toggles the signed-in user's notification preference on/off.
 *
 * After mutating the underlying state, we call `revalidatePath('/')` —
 * Next.js's recommended way to refresh the *current* page's server-rendered
 * data from inside a Server Action. It purges the cached data for the path so
 * the page is re-rendered with the updated preference on the next render,
 * without navigating/redirecting away from the current URL.
 */
export async function toggleNotifications() {
  const current = getNotificationPreference()
  const next = !current.enabled

  setNotificationPreferenceEnabled(next)

  // Refresh the current page in place. No redirect occurs.
  revalidatePath('/')
}
